with with_windows as (select *, avg(discount_pct) over (partition by channel order by discount_pct asc, id asc rows between 2 preceding and current row) as discount_pct_avg_2, row_number() over (partition by promo_code, channel order by starts_on asc, id asc) as event_seq from promotions) select date_trunc('month', ends_on) as activity_month, max(event_seq) as max_event_seq, sort_array(collect_set(channel)) as channel_list, count_if(channel = 'store') as store_events, percentile_approx(event_seq, array(0.25, 0.5, 0.75)) as event_seq_quartiles, avg(event_seq) filter (where channel = 'partner') as partner_avg_event_seq, count(case when promo_code = 'VIP' then 1 end) as vip_count from with_windows group by date_trunc('month', ends_on)
